"""InstanceNormLayer: x - mean_hw(x), then divide by sqrt(mean_hw(xc**2) + eps)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'InstanceNormLayer_7450',
    'batch': 16,
    'channels': 64,
    'height': 256,
    'width': 256,
    'eps': 1e-8,
}


def create_inputs(dtype=jnp.float32):
    shape = (CONFIG['batch'], CONFIG['channels'], CONFIG['height'], CONFIG['width'])
    x = jax.random.uniform(jax.random.key(0), shape, dtype)
    return (x,)


def workload(x):
    if x.ndim != 4:
        raise ValueError(f'expected [N, C, H, W] input, got shape {x.shape}')
    xc = x - jnp.mean(x, axis=(2, 3), keepdims=True)
    return xc / jnp.sqrt(jnp.mean(xc ** 2, axis=(2, 3), keepdims=True) + CONFIG['eps'])

"""[bf16 variant] SoftmaxAllocator: softmax(x / temperature) over the asset dimension (axis 1)."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'SoftmaxAllocator_16672',
    'n_samples': 4096,
    'n_assets': 16384,
    'temperature': 1.0,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    x = jax.random.uniform(key, (CONFIG['n_samples'], CONFIG['n_assets']), dtype)
    return (x,)


def workload(x):
    n_samples = x.shape[0]
    temperature = CONFIG['temperature'] * jnp.ones((n_samples,), dtype=x.dtype)
    inp = x / temperature[:, None]
    return jax.nn.softmax(inp, axis=1)

"""[bf16 variant] Triplet margin hinge: clamp(margin + repr[:, 1:] - repr[:, :1], 0) -> mean(dim=1) -> mean."""
import jax
import jax.numpy as jnp

CONFIG = {
    'name': 'TripletMarginLoss_8554',
    'batch': 8192,
    'queue_len_plus': 4096,
    'margin': 4.0,
}


def create_inputs(dtype=jnp.bfloat16):
    key = jax.random.key(0)
    repr_ = jax.random.uniform(key, (CONFIG['batch'], CONFIG['queue_len_plus']), dtype)
    return (repr_,)


def workload(repr_):
    pos = repr_[:, :1]
    neg = repr_[:, 1:]
    dist_hinge = jnp.maximum(CONFIG['margin'] + neg - pos, 0.0)
    return jnp.mean(jnp.mean(dist_hinge, axis=1))
